// Provided for lab 8.1 (you do not edit this file): the thread-coarsened stencil of
// book Fig. 8.10 (section 8.5, p. 194), used as a benchmark comparison.
//
// A 2D block of PLANES_IN_TILE_DIM x PLANES_IN_TILE_DIM threads marches through
// PLANES_OUT_TILE_DIM output planes in z, keeping three input planes in shared
// memory (previous, current, next) and shifting them by copying after each plane.
//
// Differs from the page:
//   - The c3/c4 pairing follows Figs. 8.6 and 8.8 (c3 with y-1, c4 with y+1). Fig. 8.10
//     prints c3 with y+1 and c4 with y-1, which gives a different answer whenever the
//     two weights differ.
//   - The tile width comes from the build's TILE_WIDTH (the listing leaves IN_TILE_DIM
//     undefined); the slab depth is PLANES_OUT_TILE_DIM, as on the page.
//   - `in` is const, the weights arrive as one StencilCoeffs argument, and the launch
//     function is ours (the book shows no host code).
#include "../lab1_stencil3d/stencil.h"

#ifndef TILE_WIDTH
#define TILE_WIDTH 32
#endif
#define PLANES_IN_TILE_DIM TILE_WIDTH
#define PLANES_OUT_TILE_DIM (PLANES_IN_TILE_DIM - 2)

__global__ void stencilPlanesKernel(const float* in, float* out, unsigned int N, StencilCoeffs c) {
    int iStart = blockIdx.z * PLANES_OUT_TILE_DIM;
    int j = blockIdx.y * PLANES_OUT_TILE_DIM + threadIdx.y - 1;
    int k = blockIdx.x * PLANES_OUT_TILE_DIM + threadIdx.x - 1;
    __shared__ float inPrev_s[PLANES_IN_TILE_DIM][PLANES_IN_TILE_DIM];
    __shared__ float inCurr_s[PLANES_IN_TILE_DIM][PLANES_IN_TILE_DIM];
    __shared__ float inNext_s[PLANES_IN_TILE_DIM][PLANES_IN_TILE_DIM];
    if (iStart - 1 >= 0 && iStart - 1 < N && j >= 0 && j < N && k >= 0 && k < N) {
        inPrev_s[threadIdx.y][threadIdx.x] = in[(iStart - 1) * N * N + j * N + k];
    }
    if (iStart >= 0 && iStart < N && j >= 0 && j < N && k >= 0 && k < N) {
        inCurr_s[threadIdx.y][threadIdx.x] = in[iStart * N * N + j * N + k];
    }
    for (int i = iStart; i < iStart + PLANES_OUT_TILE_DIM; ++i) {
        if (i + 1 >= 0 && i + 1 < N && j >= 0 && j < N && k >= 0 && k < N) {
            inNext_s[threadIdx.y][threadIdx.x] = in[(i + 1) * N * N + j * N + k];
        }
        __syncthreads();   // all three planes are in place
        if (i >= 1 && i < N - 1 && j >= 1 && j < N - 1 && k >= 1 && k < N - 1) {
            if (threadIdx.y >= 1 && threadIdx.y < PLANES_IN_TILE_DIM - 1 &&
                threadIdx.x >= 1 && threadIdx.x < PLANES_IN_TILE_DIM - 1) {
                out[i * N * N + j * N + k] = c.c0 * inCurr_s[threadIdx.y][threadIdx.x]
                                           + c.c1 * inCurr_s[threadIdx.y][threadIdx.x - 1]
                                           + c.c2 * inCurr_s[threadIdx.y][threadIdx.x + 1]
                                           + c.c3 * inCurr_s[threadIdx.y - 1][threadIdx.x]
                                           + c.c4 * inCurr_s[threadIdx.y + 1][threadIdx.x]
                                           + c.c5 * inPrev_s[threadIdx.y][threadIdx.x]
                                           + c.c6 * inNext_s[threadIdx.y][threadIdx.x];
            }
        }
        __syncthreads();   // everyone has finished reading before the planes move
        inPrev_s[threadIdx.y][threadIdx.x] = inCurr_s[threadIdx.y][threadIdx.x];
        inCurr_s[threadIdx.y][threadIdx.x] = inNext_s[threadIdx.y][threadIdx.x];
    }
}

void launchStencilPlanes(const float* in, float* out, unsigned int N, StencilCoeffs c) {
    dim3 dimBlock(PLANES_IN_TILE_DIM, PLANES_IN_TILE_DIM, 1);
    unsigned int tiles = (N + PLANES_OUT_TILE_DIM - 1) / PLANES_OUT_TILE_DIM;
    dim3 dimGrid(tiles, tiles, tiles);   // z: one block per slab of PLANES_OUT_TILE_DIM planes
    stencilPlanesKernel<<<dimGrid, dimBlock>>>(in, out, N, c);
}
